args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?person (COALESCE(?dboBirth, ?dbpBirth) AS ?birthDate) ?label WHERE {
  VALUES ?person { dbr:Frank_Kühne dbr:Subhash_Bapurao_Wankhede }
  OPTIONAL { ?person dbo:birthDate ?dboBirth. }
  OPTIONAL { ?person dbp:birthDate ?dbpBirth. }
  OPTIONAL { ?person rdfs:label ?label. FILTER(lang(?label) = 'en') }
} ORDER BY ?person

